// One item per enabled source, each carrying the profiles and the seen-set.
// The workflow deliberately holds no configuration of its own: profiles and
// sources are rows in Supabase so that adding a fourth focus is an insert.
const cfg = $input.first().json;
if (!cfg || cfg.ok !== true) {
  throw new Error('job-ingest config failed: ' + JSON.stringify(cfg).slice(0, 300));
}
const profiles = cfg.profiles || [];
const sources = cfg.sources || [];
if (profiles.length === 0) throw new Error('no enabled job_profiles — set one up in the panel first');

return sources.map((s) => ({
  json: {
    source: s,
    profiles,
    seen: cfg.seen || [],
    seen_urls: cfg.seen_urls || [],
  },
}));

