// --- node body ---
// The feed declares ISO-8859-1. n8n's HTTP node hands us a decoded string; if
// Danish characters arrive mangled, set the node's response encoding rather than
// trying to repair them here — mojibake stored once is permanent.
const ctx = $('Fan Out Sources').first().json;
const xml = $input.first().json.data ?? $input.first().json.body ?? '';
const MAX_NEW = 25; // politeness cap: each survivor costs two more fetches

const seen = new Set(ctx.seen || []);
const items = parseJobindexFeed(xml)
  .filter((i) => i.url && !seen.has('jobindex_rss ' + i.external_id))
  .slice(0, MAX_NEW);

return items.map((i) => ({ json: { ...i, source_id: ctx.source.id } }));

