// --- node body ---
// A /vis-job/ page is a stub: banner, title link, location. The ad body lives one
// hop further on, at the <h4> link. Items whose target cannot be resolved are
// kept and fall back to the RSS title plus the og:description lead — a thin row
// is more useful than a dropped one, and the gate can still see the title.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const html = items[i].json.data ?? items[i].json.body ?? '';
  const meta = $('Parse Feed').all()[i]?.json ?? {};
  const stub = extractJobindexStub(html);
  out.push({ json: { ...meta, ...stub, stub_only: !stub.target_url } });
}
return out;

