// --- node body ---
// An employer page may carry schema.org JobPosting even though Jobindex does not
// — several ATS vendors do. Prefer it when present, fall back to readable text.
const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const html = items[i].json.data ?? items[i].json.body ?? '';
  const meta = $('Parse Stub').all()[i]?.json ?? {};
  const ld = extractJobPostingLd(html);
  const fromLd = ld ? normalizeLdJobPosting(ld, { url: meta.url, sourceKind: 'jobindex_rss' }) : null;
  const description = pickDescription(meta.lead, fromLd?.description, extractReadableText(html));
  const company = meta.company || fromLd?.company || null;
  const title = meta.title || fromLd?.title || '';
  out.push({
    json: {
      source_kind: 'jobindex_rss',
      source_id: meta.source_id ?? null,
      url: meta.url,
      source_url: meta.target_url ?? null,
      apply_url: meta.target_url ?? null,
      external_id: meta.external_id,
      dedupe_key: dedupeKey(company, title),
      title,
      company,
      location: meta.location ?? fromLd?.location ?? null,
      remote: meta.remote ?? fromLd?.remote ?? null,
      employment_type: fromLd?.employment_type ?? null,
      posted_at: meta.posted_at ?? null,
      valid_through: fromLd?.valid_through ?? null,
      description,
      ld_json: ld ?? null,
      apply_channel: 'ats',
      categories: meta.categories ?? [],
    },
  });
}
return out;

// The sitemap lists ~1200 job URLs. Fetching all of them on the first run — when
// EVERYTHING is new — is what gets a crawler blocked, and losing the source is a
// permanent cost against a one-off saving. Diff against what we already have and
// take a capped slice per run; the backlog drains over a few runs.
const ctx = $('Fan Out Sources').first().json;
const xml = $input.first().json.data ?? $input.first().json.body ?? '';
const MAX_NEW = 30;

const seen = new Set(ctx.seen_urls || []);
const locs = [...xml.matchAll(/<loc>([^<]+)<\/loc>/g)].map((m) => m[1].trim());
const fresh = locs.filter((u) => /\/jobs\//.test(u) && !seen.has(u)).slice(0, MAX_NEW);

if (fresh.length === 0) return [];
return fresh.map((u) => ({ json: { url: u, source_id: ctx.source.id } }));

